<script>
    document.addEventListener('DOMContentLoaded', function () {

        const modalEl = document.getElementById('searchModal');
        const modal = bootstrap.Modal.getOrCreateInstance(modalEl);
        const searchInput = modalEl.querySelector('input');

        let items = [];
        let currentIndex = -1;

        const activeClass = 'selected';

        function collectItems() {
            items = Array.from(modalEl.querySelectorAll('.search-item'))
                .filter(el => el.style.display !== 'none');
        }

        function clearSelection() {
            items.forEach(el => el.classList.remove(activeClass));
        }

        function selectItem(index) {
            if (!items.length) return;

            clearSelection();
            currentIndex = index;

            const el = items[currentIndex];
            el.classList.add(activeClass);

            el.scrollIntoView({
                block: 'nearest',
                behavior: 'smooth'
            });
        }

        function filterResults(query) {
            query = (query || '').toLowerCase().trim();

            const allItems = modalEl.querySelectorAll('.search-item');
            let visibleCount = 0;

            allItems.forEach(item => {
                const text = item.textContent.toLowerCase();
                const match = !query || text.includes(query);

                item.style.display = match ? 'block' : 'none';

                if (match) visibleCount++;
            });

            const appSection = document.getElementById('application-section');
            if (appSection) {
                const visibleApps = appSection.querySelectorAll('.search-item[style*="flex"]');
                appSection.style.display = visibleApps.length ? '' : 'none';
            }

            const container = modalEl.querySelector('.search-body .py-4');
            if (container) {

                const children = Array.from(container.children);

                let currentGroup = null;
                let groupItems = [];

                function processGroup(groupEl, items) {
                    if (!groupEl) return;

                    const hasVisible = items.some(item => item.style.display !== 'none');

                    groupEl.style.display = hasVisible ? '' : 'none';

                    let next = groupEl.nextElementSibling;

                    while (next && !next.classList.contains('search-group')) {

                        if (next.tagName === 'HR') {
                            next.style.display = hasVisible ? '' : 'none';
                        }

                        next = next.nextElementSibling;
                    }
                }

                children.forEach(el => {

                    if (el.classList.contains('search-group')) {

                        processGroup(currentGroup, groupItems);

                        currentGroup = el;
                        groupItems = [];

                    } else if (el.classList.contains('search-item')) {

                        groupItems.push(el);
                    }

                });

                processGroup(currentGroup, groupItems);
            }

            let old = modalEl.querySelector('.no-results');
            if (old) old.remove();

            if (query && visibleCount === 0) {
                modalEl.querySelector('.search-body').insertAdjacentHTML('beforeend', `
                <div class="no-results opacity-50 text-center py-5 text-muted">
                    No results found
                </div>
            `);
            }

            collectItems();
            currentIndex = -1;

            if (items.length) {
                selectItem(0);
            }
        }

        modalEl.addEventListener('shown.bs.modal', () => {
            searchInput.focus();
            filterResults('');
        });

        searchInput.addEventListener('input', () => {
            filterResults(searchInput.value);
        });

        document.addEventListener('keydown', function (e) {

            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
                e.preventDefault();

                if (modalEl.classList.contains('show')) {
                    modal.hide();
                } else {
                    modal.show();
                }
                return;
            }

            if (e.key === 'Escape') {
                modal.hide();
                return;
            }

            if (!modalEl.classList.contains('show')) return;

            if (['ArrowDown', 'ArrowUp', 'Tab', 'Enter'].includes(e.key)) {
                e.preventDefault();
            }

            if (e.key === 'ArrowDown' || (e.key === 'Tab' && !e.shiftKey)) {
                collectItems();
                if (!items.length) return;

                const next = (currentIndex + 1) % items.length;
                selectItem(next);
            }

            if (e.key === 'ArrowUp' || (e.key === 'Tab' && e.shiftKey)) {
                collectItems();
                if (!items.length) return;

                const prev = (currentIndex - 1 + items.length) % items.length;
                selectItem(prev);
            }

            if (e.key === 'Enter') {
                if (currentIndex === -1) return;

                const el = items[currentIndex];
                const link = el.querySelector('a');

                if (link && link.href) {
                    window.location.href = link.href;
                }
            }
        });

    });
</script>

