<!--notification with local storage-->
<script>
    document.addEventListener('DOMContentLoaded', function () {


        const origin = window.location.origin;
        const firstFolder = window.location.pathname.split('https://ignou-phd.samarth.edu.in/')[1];
        const baseUrl = origin + '/' + firstFolder;

        const STORAGE_KEY = 'read_notifications_' + baseUrl;

        const totalUnreadFromServer = 0;

        const stored = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];

        function updateUnreadText() {
            const totalUnreadFromServer = 0;

            const stored = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];

            const finalUnread = Math.max(totalUnreadFromServer - stored.length, 0);
            $('#unreadCount').text('Unread (' + finalUnread + ')');
        }

        updateUnreadText();

        let readNotifications = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];

        const badges = [
            document.getElementById('notificationBadge'),
            document.getElementById('guestNotificationBadge'),
            document.getElementById('guestNotificationdot')
        ].filter(Boolean);


        function markAsRead(id) {

            id = String(id);

            if (!readNotifications.includes(id)) {
                readNotifications.push(id);
                localStorage.setItem(STORAGE_KEY, JSON.stringify(readNotifications));
            }

            document.querySelectorAll('.notification-item').forEach(item => {
                if (item.dataset.id === id) {
                    let dot = item.querySelector('.notification-dot, .new-badge-danger, .new-badge-danger-index');
                    if (dot) dot.remove();

                    item.dataset.new = "0";
                }
            });

            document.querySelectorAll('.view-notice-btn').forEach(btn => {
                if (btn.dataset.id === id) {

                    btn.innerHTML = 'View Notice <span class="ps-2"> -></span>';

                    // remove ALL possible "new" styles
                    btn.classList.remove(
                        'btn-dark',
                        'bg-primary',
                        'bg-opacity-10',
                        'hover-arrow-active',
                        'text-primary'
                    );

                    // add "read" styles
                    btn.classList.add(
                        'bg-secondary',
                        'bg-opacity-10',
                        'text-dark',
                        'hover-arrow-noactive'
                    );
                }
            });

            document.querySelectorAll('.notification-grid-item').forEach(item => {

                if (item.dataset.id === id) {

                    let badge = item.querySelector('.new-badge-danger');
                    if (badge) badge.remove();

                    let btn = item.querySelector('.view-doc-btn');
                    if (btn) {
                        btn.innerText = 'View Notice';

                        btn.classList.remove('btn-dark');
                        btn.classList.add('btn-secondary');

                        btn.dataset.new = "0";
                    }

                    item.dataset.new = "0";
                }
            });


            updateHeaderBadge();
            toggleMarkAllButton();
            updateUnreadText();
        }

        function toggleMarkAllButton() {
            const markBtn = document.getElementById('mark_btn');

            if (!markBtn) return;

            let allIds = [];

            document.querySelectorAll('.notification-item').forEach(item => {
                if (item.dataset.id) {
                    allIds.push(String(item.dataset.id));
                }
            });

            const unread = allIds.filter(id => !readNotifications.includes(id));

            if (unread.length === 0) {
                markBtn.style.display = 'none'; // hide
            } else {
                markBtn.style.display = 'block'; // show
            }
        }

        function updateHeaderBadge() {

            badges.forEach(badge => {

                let allIds = JSON.parse(badge.getAttribute('data-ids') || '[]');

                let unread = allIds.filter(id =>
                    !readNotifications.includes(String(id))
                );

                let count = unread.length;

                if (count > 0) {
                    badge.classList.remove('d-none');

                    // dot vs count
                    if (badge.id === 'guestNotificationdot') {
                        badge.innerText = '';
                    } else {
                        badge.innerText = count;
                    }

                } else {
                    badge.classList.add('d-none');
                }
            });
        }


        document.querySelectorAll('.notification-item').forEach(item => {

            item.addEventListener('click', function (e) {

                const id = item.dataset.id;

                if (item.tagName === 'A') {
                    e.preventDefault();

                    markAsRead(id);

                    setTimeout(() => {
                        window.open(item.href, '_blank');
                    }, 100);

                } else {
                    markAsRead(id);
                }
            });
        });

        document.querySelectorAll('.view-notice-btn').forEach(btn => {

            btn.addEventListener('click', function (e) {

                e.stopPropagation();

                const id = btn.dataset.id;
                markAsRead(id);
            });
        });


        document.querySelectorAll('.notification-item').forEach(item => {

            const id = String(item.dataset.id);

            if (readNotifications.includes(id)) {

                let dot = item.querySelector('.notification-dot, .new-badge-danger, .new-badge-danger-index');
                if (dot) dot.remove();

                item.dataset.new = "0";

                let btn = document.querySelector('.view-notice-btn[data-id="' + id + '"]');

                if (btn) {
                    btn.innerHTML = 'View Notice <span class="ps-2"> -></span>';

                    btn.classList.remove(
                        'btn-dark',
                        'bg-primary',
                        'bg-opacity-10',
                        'hover-arrow-active',
                        'text-primary'
                    );

                    btn.classList.add(
                        'bg-secondary',
                        'bg-opacity-10',
                        'text-dark',
                        'hover-arrow-noactive'
                    );
                }
            }
        });


        const markAllBtn = document.getElementById('markAllBtn');

        if (markAllBtn) {
            markAllBtn.addEventListener('click', function (e) {

                e.preventDefault();
                e.stopPropagation();

                const badge = document.getElementById('notificationBadge');

                let allIds = [];

                if (badge) {
                    allIds = JSON.parse(
                        badge.getAttribute('data-ids') || '[]'
                    ).map(id => String(id));
                }

                readNotifications = [...new Set([...readNotifications, ...allIds])];

                localStorage.setItem(STORAGE_KEY, JSON.stringify(readNotifications));

                document.querySelectorAll('.notification-dot, .new-badge-danger, .new-badge-danger-index').forEach(dot => {
                    dot.remove();
                });

                document.querySelectorAll('.notification-item').forEach(item => {
                    item.dataset.new = "0";
                });

                document.querySelectorAll('.view-notice-btn').forEach(btn => {
                    btn.innerHTML = 'View Notice <span class="ps-2"> -></span>';

                    btn.classList.remove(
                        'btn-dark',
                        'bg-primary',
                        'bg-opacity-10',
                        'hover-arrow-active',
                        'text-primary'
                    );

                    btn.classList.add(
                        'bg-secondary',
                        'bg-opacity-10',
                        'text-dark',
                        'hover-arrow-noactive'
                    );
                });

                updateHeaderBadge();
                toggleMarkAllButton();
            });
        }


        updateHeaderBadge();
        toggleMarkAllButton();
    });
</script>
