<script>
    document.querySelectorAll('#notificationTabs .nav-link').forEach(tab => {
        tab.addEventListener('click', function (e) {

            e.preventDefault();
            e.stopPropagation();

            document.querySelectorAll('#notificationTabs .nav-link')
                .forEach(t => t.classList.remove('active'));

            this.classList.add('active');

            const type = this.getAttribute('data-tab');

            let visibleCount = 0;

            document.querySelectorAll('.notification-item').forEach(item => {

                const li = item.closest('li');
                const hrLi = li.nextElementSibling;

                let show = false;

                if (type === 'all') {
                    show = true;
                } else {
                    const isNew = item.getAttribute('data-new') === '1';
                    show = isNew;
                }

                li.style.display = show ? 'block' : 'none';

                if (show) visibleCount++;

                if (hrLi && hrLi.querySelector('.dropdown-divider')) {
                    hrLi.style.display = show ? 'block' : 'none';
                }
            });

            const emptyState = document.getElementById('unreadEmptyState');

            if (emptyState) {
                if (type === 'new' && visibleCount === 0) {
                    emptyState.style.display = 'block';
                } else {
                    emptyState.style.display = 'none';
                }
            }

            const allLis = document.querySelectorAll('.notification-list > li');

            allLis.forEach((li, index) => {
                if (li.querySelector('.dropdown-divider')) {
                    const prev = allLis[index - 1];
                    const next = allLis[index + 1];

                    const prevVisible = prev && prev.style.display !== 'none';
                    const nextVisible = next && next.style.display !== 'none';

                    li.style.display = (prevVisible && nextVisible) ? 'block' : 'none';
                }
            });

        });
    });
</script>
