<script>
    document.addEventListener('DOMContentLoaded', function () {
        const origin = window.location.origin;
        const firstFolder = window.location.pathname.split('https://ignou-phd.samarth.edu.in/')[1];
        const baseUrl = origin + '/' + firstFolder;

        const STORAGE_KEY_FAQ = 'faq_read_items_' + baseUrl;

        const NEW_TIME_LIMIT = 15552000;

        function getReadItems() {
            return JSON.parse(localStorage.getItem(STORAGE_KEY_FAQ)) || [];
        }

        function markAsRead(id) {
            let items = getReadItems();

            if (!items.includes(id)) {
                items.push(id);
                localStorage.setItem(STORAGE_KEY_FAQ, JSON.stringify(items));
            }
            updateHeaderFaqCount();

        }


        const readItems = getReadItems();
        const currentTime = Math.floor(Date.now() / 1000);

        let unreadCount = 0;
        updateHeaderFaqCount();

        //  const badge = document.getElementById('faqBadge');
        // if (badge) {
        //     badge.innerText = unreadCount;
        //
        //     if (unreadCount === 0) {
        //         badge.style.display = 'none';
        //     }
        // }

        const badge = document.getElementById('faqBadge');


        const guestDot = document.getElementById('guestfaqdot');

        if (guestDot) {

            let newIds = [];

            try {

                newIds = JSON.parse(guestDot.dataset.ids || "[]");

            } catch (e) {

                console.error('Invalid JSON in data-ids');
            }

            const unreadGuestIds = newIds.filter(id =>
                !readItems.includes(String(id))
            );

            if (unreadGuestIds.length > 0) {

                guestDot.classList.remove('d-none');
                guestDot.style.display = '';

            } else {

                guestDot.classList.add('d-none');
                guestDot.style.display = 'none';
            }
        }
        document.querySelectorAll('.faq-dropdown a.dropdown-item').forEach(link => {

            link.addEventListener('click', function () {

                const href = this.getAttribute('href');
                const match = href.match(/#faq-(\d+)/);

                if (!match) return;

                const id = String(match[1]);

                markAsRead(id);

                const dot = this.querySelector('.faq-dot');
                if (dot) dot.classList.add('d-none');

            });

        });

        function updateHeaderFaqCount() {

            const readItems = getReadItems();

            // category dots
            document.querySelectorAll('.faq-category-item').forEach(item => {

                const ids = JSON.parse(item.dataset.ids || '[]');

                const hasUnread = ids.some(id =>
                    !readItems.includes(String(id))
                );

                const dot = item.querySelector('.category-dot');

                if (!dot) return;

                if (hasUnread) {
                    dot.classList.remove('d-none');
                } else {
                    dot.classList.add('d-none');
                }
            });

            // top badge
            const badge = document.getElementById('faqBadge');

            if (badge) {

                // unread category count
                const categoryItems = document.querySelectorAll('.faq-category-item');

                let unreadCategoryCount = 0;

                categoryItems.forEach(item => {

                    const ids = JSON.parse(item.dataset.ids || '[]');

                    const hasUnread = ids.some(id =>
                        !readItems.includes(String(id))
                    );

                    if (hasUnread) {
                        unreadCategoryCount++;
                    }
                });

                badge.innerText = unreadCategoryCount > 9
                    ? '9+'
                    : unreadCategoryCount;

                if (unreadCategoryCount > 0) {

                    badge.innerText = unreadCategoryCount > 9
                        ? '9+'
                        : unreadCategoryCount;

                    badge.classList.remove('d-none');
                    badge.style.display = '';

                } else {

                    badge.innerText = '';

                    badge.classList.add('d-none');
                    badge.style.display = 'none';
                }
            }

            // guest dot
            const guestDot = document.getElementById('guestfaqdot');

            if (guestDot) {

                let newIds = JSON.parse(guestDot.dataset.ids || "[]");

                const hasUnread = newIds.some(id =>
                    !readItems.includes(String(id))
                );

                if (hasUnread) {

                    guestDot.classList.remove('d-none');
                    guestDot.style.display = '';

                } else {

                    guestDot.classList.add('d-none');
                    guestDot.style.display = 'none';
                }

            }
        }


    });
</script>
