<script>
    document.addEventListener('DOMContentLoaded', function () {

        const container = document.querySelector('.useful_link_body');
        const searchInput = document.getElementById('useful_links');

        const noResult = document.createElement('div');

        noResult.innerText = 'No Result Found.';
        noResult.className = 'text-secondary opacity-75 text-center';

        noResult.style.cssText = `
        display: none;
        min-height: 200px;
        align-items: center;
        justify-content: center;
    `;

        container.appendChild(noResult);

        searchInput.addEventListener('input', function () {

            const value = this.value
                .toLowerCase()
                .replace(/\s+/g, ' ')
                .trim();

            let totalFound = 0;

            const sections = container.querySelectorAll('.link-section');

            sections.forEach(section => {

                const badges = section.querySelectorAll('.search-badge');

                let sectionFound = 0;

                let matchedBadges = [];

                badges.forEach(badge => {

                    const textEl = badge.querySelector('.search-text');

                    if (!textEl) return;

                    const cloned = textEl.cloneNode(true);

                    const badgeTexts = [];

                    cloned.querySelectorAll('.badge').forEach(el => {

                        const badgeText = el.textContent
                            .toLowerCase()
                            .replace(/\s+/g, ' ')
                            .trim();

                        if (badgeText) {
                            badgeTexts.push(badgeText);
                        }
                    });

                    const allText = cloned.textContent
                        .toLowerCase()
                        .replace(/\s+/g, ' ')
                        .trim();

                    const text = (
                        allText + ' ' + badgeTexts.join(' ')
                    )
                        .toLowerCase()
                        .replace(/\s+/g, ' ')
                        .trim();

                    const exactMatch = text === value;

                    const startsWithMatch =
                        text.startsWith(value);

                    const includesMatch =
                        text.includes(value);

                    if (
                        value === '' ||
                        exactMatch ||
                        startsWithMatch ||
                        includesMatch
                    ) {

                        matchedBadges.push({
                            badge,
                            exactMatch,
                            startsWithMatch
                        });

                        badge.style.setProperty(
                            'display',
                            'inline-flex',
                            'important'
                        );

                        sectionFound++;
                        totalFound++;

                        highlightText(textEl, value);

                        const isProfileBadge =
                            textEl.textContent.includes('My Profile');

                        const statusBadge = isProfileBadge
                            ? badge.querySelector('.badge')
                            : null;

                        if (statusBadge) {

                            statusBadge.classList.remove(
                                'bg-danger',
                                'bg-warning',
                                'bg-success',
                                'bg-dark'
                            );

                            if (value !== '') {

                                statusBadge.classList.add(
                                    'bg-dark',
                                    'text-white'
                                );

                            } else {

                                const badgeText =
                                    statusBadge.textContent.trim();

                                if (badgeText === 'Not Submitted') {

                                    statusBadge.classList.add('bg-danger');

                                } else if (badgeText === 'Pending') {

                                    statusBadge.classList.add('bg-warning');

                                } else if (badgeText === 'Submitted') {

                                    statusBadge.classList.add('bg-success');
                                }
                            }
                        }

                    } else {

                        badge.style.setProperty(
                            'display',
                            'none',
                            'important'
                        );

                        highlightText(textEl, '');
                    }

                });

                if (value !== '') {

                    const hasExactMatch = matchedBadges.some(
                        item => item.exactMatch
                    );

                    if (hasExactMatch) {

                        badges.forEach(badge => {

                            badge.style.setProperty(
                                'display',
                                'none',
                                'important'
                            );
                        });

                        matchedBadges
                            .filter(item => item.exactMatch)
                            .forEach(item => {

                                item.badge.style.setProperty(
                                    'display',
                                    'inline-flex',
                                    'important'
                                );
                            });

                        sectionFound = matchedBadges.filter(
                            item => item.exactMatch
                        ).length;

                    } else {

                        const hasStartsWithMatch = matchedBadges.some(
                            item => item.startsWithMatch
                        );

                        if (hasStartsWithMatch) {

                            badges.forEach(badge => {

                                badge.style.setProperty(
                                    'display',
                                    'none',
                                    'important'
                                );
                            });

                            matchedBadges
                                .filter(item => item.startsWithMatch)
                                .forEach(item => {

                                    item.badge.style.setProperty(
                                        'display',
                                        'inline-flex',
                                        'important'
                                    );
                                });

                            sectionFound = matchedBadges.filter(
                                item => item.startsWithMatch
                            ).length;
                        }
                    }
                }

                const shouldHide =
                    (value !== '' && sectionFound === 0);

                section.style.display =
                    shouldHide ? 'none' : '';

                const prevDiv = section.previousElementSibling;

                if (prevDiv && prevDiv.querySelector('hr')) {

                    prevDiv.style.display =
                        shouldHide ? 'none' : '';
                }

            });

            noResult.style.display =
                (value !== '' && totalFound === 0)
                    ? 'flex'
                    : 'none';

        });

        function highlightText(element, query) {

            if (!element) return;

            if (!element.hasAttribute('data-original-html')) {

                element.setAttribute(
                    'data-original-html',
                    element.innerHTML
                );
            }

            const originalHTML =
                element.getAttribute('data-original-html');

            if (!query) {

                element.innerHTML = originalHTML;

                return;
            }

            const temp = document.createElement('div');

            temp.innerHTML = originalHTML;

            const regex = new RegExp(`(${query})`, 'gi');

            function walk(node) {

                if (node.nodeType === 3) {

                    const replaced = node.nodeValue.replace(
                        regex,
                        '<b>$1</b>'
                    );

                    if (replaced !== node.nodeValue) {

                        const span = document.createElement('span');

                        span.innerHTML = replaced;

                        node.replaceWith(...span.childNodes);
                    }

                } else {

                    node.childNodes.forEach(walk);
                }
            }

            walk(temp);

            element.innerHTML = temp.innerHTML;
        }

        const usefulInput =
            document.getElementById('useful_links');

        const clearUsefulBtn =
            document.getElementById('clearUsefulLinks');

        usefulInput.addEventListener('keyup', function () {

            if (this.value.trim().length > 0) {

                clearUsefulBtn.classList.remove('d-none');

            } else {

                clearUsefulBtn.classList.add('d-none');
            }
        });

        clearUsefulBtn.addEventListener('click', function () {

            usefulInput.value = '';

            this.classList.add('d-none');

            usefulInput.dispatchEvent(
                new Event('input')
            );
        });

    });
</script>
