<script>
    function copyRefNo(el) {
        const textEl = el.parentElement.querySelector(".refNoText");

        if (!textEl) {
            console.error("refNoText not found");
            return;
        }

        const text = textEl.innerText;

        navigator.clipboard.writeText(text).then(() => {
             el.classList.remove("bi-copy");
            el.classList.add("bi-check-circle-fill");

             el.style.color = "#5c60f5";
             setTimeout(() => {
                el.classList.remove("bi-check-circle-fill");
                el.classList.add("bi-copy");
                el.style.color = "";
            }, 2000);

        }).catch(err => {
            console.error("Clipboard error:", err);
        });
    }
</script>

<script>
    document.addEventListener('click', function (e) {

        const btn = e.target.closest('.view-notice-btn');
        if (!btn) return;

        const id = btn.dataset.id;
             const STORAGE_KEY = 'read_notifications_' + window.location.hostname;
         let read = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];

         if (!read.includes(id)) {
            read.push(id);
            localStorage.setItem(STORAGE_KEY, JSON.stringify(read));
        }

         const item = document.querySelector('.notification-item[data-id="' + id + '"]');
        if (item) {
            const dot = item.querySelector('.new-badge-danger-index');
            if (dot) dot.style.display = 'none';
        }

         btn.classList.remove('bg-primary', 'bg-opacity-10', 'text-primary','hover-arrow-active');
        btn.classList.add('bg-secondary', 'bg-opacity-10', 'text-dark','hover-arrow-noactive');

        btn.innerHTML = 'View Notice <span class="ps-2"> -></span>';
    });
    document.addEventListener('DOMContentLoaded', function () {

        const STORAGE_KEY = 'read_notifications_' + window.location.hostname;
        let read = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];

        document.querySelectorAll('.notification-item').forEach(item => {

            const id = item.dataset.id;

            if (read.includes(id)) {

                 const dot = item.querySelector('.new-badge-danger-index');
                if (dot) dot.style.display = 'none';

                 const btn = document.querySelector('.view-notice-btn[data-id="' + id + '"]');
                if (btn) {
                    btn.classList.remove('bg-primary', 'bg-opacity-10', 'text-primary','hover-arrow-active');
                    btn.classList.add('bg-secondary', 'bg-opacity-10', 'text-dark','hover-arrow-noactive');

                    btn.innerHTML = 'View Notice <span class="ps-2"> -></span>';
                }
            }
        });
    });
