//            $('#programme-list').html(programmeHtml || '<p class="text-muted">No data found</p>');

   
             let applications = res.applications || [];

            if (applications.length > 0) {
                $('#application-section').show();
                $('#application-count').text(res.application_count ?? applications.length);

                let appHtml = '';
                applications.forEach(item => {
    const statusClass = item.status === 'Submit' ? 'text-success' : 'text-danger';

    appHtml += `
    <div class="d-flex align-items-center mb-4 search-item ps-3">
        <i class="bi bi-mortarboard me-3 text-dark bg-secondary bg-opacity-20 rounded-2 py-1 px-2 fs-7"></i>
        <div>
            <div class="fw-semibold text-dark fs-7">${item.programme_name}</div>
            <p class="${statusClass} fs-7">${item.status}</p>
        </div>
    </div>`;
});

                $('#application-list').html(appHtml);
            } else {
                $('#application-section').hide();
            }
        },

        error: function (err) {
            console.log("AJAX ERROR:", err);
            $('#programme-list').html('<p class="text-danger">Failed to load data</p>');
            $('#ou-list').html('<p class="text-danger">Failed to load data</p>');
        }
    });
}



