<script>
     document.addEventListener("DOMContentLoaded", function () {

        const scrollContainer = document.body;

        const progressCircle = document.getElementById("progressCircle");
        const wrapperTop = document.getElementById("scrollTrackerWrapper");
        const backToTopBtn = document.getElementById("backToTopBtn");

        if (!scrollContainer) return;

        const radius = 45;
        const circumference = 2 * Math.PI * radius;

        if (progressCircle) {
            progressCircle.style.strokeDasharray = circumference;
        }

        let isAtTop = true;

        scrollContainer.addEventListener("scroll", function () {

            const scrollTop = scrollContainer.scrollTop;
            const scrollHeight = scrollContainer.scrollHeight - scrollContainer.clientHeight;

            if (scrollHeight <= 0) {
                if (wrapperTop) wrapperTop.style.display = "none";
                return;
            }

            const scrollPercent = scrollTop / scrollHeight;

            if (progressCircle) {
                const offset = circumference - scrollPercent * circumference;
                progressCircle.style.strokeDashoffset = offset;
            }

            if (wrapperTop) wrapperTop.style.display = "block";

            if (scrollTop <= 10) {
                isAtTop = true;
                backToTopBtn.classList.add("rotate-down");
            } else {
                isAtTop = false;
                backToTopBtn.classList.remove("rotate-down");
            }

            if (wrapperTop) {
                if (scrollPercent >= 0.8) {
                    wrapperTop.style.opacity = "0";
                    wrapperTop.style.pointerEvents = "none";
                } else {
                    wrapperTop.style.opacity = "1";
                    wrapperTop.style.pointerEvents = "auto";
                }
            }

        });

        if (backToTopBtn) {
            backToTopBtn.addEventListener("click", function () {

                if (isAtTop) {
                    scrollContainer.scrollTo({
                        top: scrollContainer.scrollHeight,
                        behavior: "smooth"
                    });
                } else {
                    scrollContainer.scrollTo({
                        top: 0,
                        behavior: "smooth"
                    });
                }

            });
        }

    });

</script>

<script>

    document.addEventListener('DOMContentLoaded', function () {

        const selectors = '.navbar a, .sidebar a';

        document.querySelectorAll(selectors).forEach(link => {
            if (link.closest('.notification-item')) return;

            const href = link.getAttribute('href');
            if (!href) return;

            if (
                href.startsWith('#') ||
                href.startsWith('javascript:') ||
                href.startsWith('mailto:') ||
                href.startsWith('tel:')
            ) return;

            const isExternal = href.startsWith('http') && !href.includes(window.location.hostname);

            if (isExternal) {

                if (link.querySelector('.external-link-icon')) return;

                const icon = document.createElement('i');
                icon.className = 'bi bi-arrow-up-right external-link-icon ms-2';
                icon.style.fontSize = '12px';

                link.appendChild(icon);

                link.setAttribute('target', '_blank');
                link.setAttribute('rel', 'noopener noreferrer');
            }

        });

    });

</script>




<script>
(function () {

  function bindUmami() {
    if (!window.umami) return setTimeout(bindUmami, 100);

    const identity = window.__UMAMI_IDENTITY__;
    if (!identity || !identity.id) return;

    if (window.__UMAMI_IDENTIFIED__) return;
    window.__UMAMI_IDENTIFIED__ = true;

    window.umami.identify(identity.id, identity.traits);

    console.log("Umami Identity Attached:", identity);
  }

  bindUmami();

})();
</script>